// Bench wiring smoke test.
//
// Replaces the default counter test generated by `flutter create` (it
// never matched this app). This mirrors lib/main.dart's construction
// sequence against a temporary Hive directory - no network, no widget
// pumping: if the bench's imports, constructors or the engine /
// compressor / storage initialize() chain ever break, `flutter test`
// fails here first.

import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:hive/hive.dart';

import 'package:calli_archiviste/calli_archiviste.dart';
import 'package:calli_bench/main.dart' show kUserName;

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  test('bench wiring constructs the real engine end to end', () async {
    final tempDir =
        await Directory.systemTemp.createTemp('calli_bench_test');
    try {
      Hive.init(tempDir.path);

      final llm = KoboldLocalService.fromConfig();
      final storage = SessionStorage();
      await storage.initialize();
      final intakeStorage = IntakeStorage();
      await intakeStorage.initialize();

      final compressor = ContextCompressor(llm: llm, userName: kUserName);
      await compressor.initialize();

      final engine = InterviewEngine(
        llm: llm,
        contextCompressor: compressor,
        storage: storage,
        // No PKC in the bench, matching lib/main.dart.
        pkcRetrievalEnabled: false,
        pkcModelEnrichmentEnabled: false,
        userName: kUserName,
      );
      await engine.initialize();

      final provider = InterviewProvider(
        engine: engine,
        storage: storage,
        intakeStorage: intakeStorage,
      );

      expect(provider.currentSession, isNull);
      expect(kUserName, 'Dave');
    } finally {
      await Hive.close();
      tempDir.deleteSync(recursive: true);
    }
  });
}
